#[inductive(consume_end)]
fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
    let head = pre.consumer.get_Consuming_0();
    let next_head = Self::inc_wrap(head, pre.len());

    // Establish facts about the transition
    assert(pre.consumer == ConsumerState::Consuming(head));
    assert(post.consumer == ConsumerState::Idle(next_head));
    assert(post.head == next_head);
    assert(pre.head == head);

    // Verify the deposited permission meets requirements
    assert(perm.id() == pre.backing_cells.index(head as int));
    assert(perm.is_uninit());

    // Prove the invariant holds for all indices
    assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        if i == head {
            // Special case: this is the cell we just deposited back
            assert(post.storage.dom().contains(i));
            assert(post.storage.index(i).id() == post.backing_cells.index(i as int));
            // After consuming, this cell should be uninit (empty)
            // Check if it's in the active range (should be false since we consumed it)
            assert(!post.in_active_range(i));
            assert(post.storage.index(i).is_uninit());
            assert(post.valid_storage_at_idx(i));
        } else {
            // For all other cells, show their status is preserved appropriately

            // Check if this cell was checked out before the transition
            if pre.is_checked_out(i) {
                // If checked out before, it should still be checked out or now in storage
                if post.is_checked_out(i) {
                    // Still checked out
                    assert(!post.storage.dom().contains(i));
                    assert(post.valid_storage_at_idx(i));
                } else {
                    // Was checked out, now should be in storage
                    // But this shouldn't happen except for the head cell we're handling separately
                    assert(false);
                }
            } else {
                // If not checked out before, permission should be and remain in storage
                assert(pre.storage.dom().contains(i));
                assert(post.storage.dom().contains(i));
                assert(post.storage.index(i).id() == post.backing_cells.index(i as int));

                // The initialized/uninitialized status depends on whether it's in active range
                if post.in_active_range(i) {
                    // Should be initialized
                    assert(pre.in_active_range(i));
                    assert(pre.storage.index(i).is_init());  
                    assert(post.storage.index(i).is_init());
                } else {
                    // Should be uninitialized
                    if pre.in_active_range(i) {
                        // Was active, now inactive - but this should only happen for the head cell
                        assert(i == head);
                        assert(false); // contradiction, handled above
                    } else {
                        // Was already inactive
                        assert(pre.storage.index(i).is_uninit());
                        assert(post.storage.index(i).is_uninit());
                    }
                }
                assert(post.valid_storage_at_idx(i));
            }
        }
    }
}

