#[inductive(consume_end)]
fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
    let head = pre.consumer.get_Consuming_0();
    let next_head = Self::inc_wrap(head, pre.len());

    // Facts from the transition
    assert(pre.consumer == ConsumerState::Consuming(head));
    assert(post.consumer == ConsumerState::Idle(next_head));
    assert(pre.head == head);
    assert(post.head == next_head);

    // Preconditions for deposit operation
    assert(perm.id() == pre.backing_cells.index(head as int));
    assert(perm.is_uninit());

    // Pre-state facts about head cell
    assert(pre.is_Checked_Out(head));  // head cell was checked out
    assert(!pre.storage.dom().contains(head));  // so not in storage

    // Key insight: in the pre-state, head was in the active range (since it was consumed)
    assert(pre.in_active_range(head));

    // Prove the invariant holds
    assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        if i == head {
            // Special case: the cell we just deposited back
            assert(post.storage.dom().contains(i));
            assert(post.storage.index(i).id() == post.backing_cells.index(i as int));
            // After consumption, this cell becomes empty (uninit)
            assert(!post.in_active_range(i));  // No longer in active range
            assert(post.storage.index(i).is_uninit());
            assert(post.valid_storage_at_idx(i));
        } else {
            // All other cells should maintain their validity property

            // Preservation of checked-out status
            assert((post.is_checked_out(i) <==> pre.is_checked_out(i)));

            if post.is_checked_out(i) {
                // Checked out in post-state
                assert(!post.storage.dom().contains(i));
                assert(post.valid_storage_at_idx(i));
            } else {
                // In storage in post-state
                assert(post.storage.dom().contains(i));
                assert(post.storage.index(i).id() == post.backing_cells.index(i as int));

                // Content preservation 
                if post.in_active_range(i) {
                    // Should be initialized
                    assert(pre.in_active_range(i)); // Active range only shrinks
                    assert(pre.storage.index(i).is_init());
                    assert(post.storage.index(i).is_init());
                } else {
                    // Should be uninitialized
                    if pre.in_active_range(i) {
                        // Was active but now inactive
                        // This happens only when head advances past i 
                        assert(i == head);
                        assert(false); // Contradiction - handled in special case above
                    } else {
                        // Was already inactive
                        assert(pre.storage.index(i).is_uninit());
                        assert(post.storage.index(i).is_uninit());
                    }
                }
                assert(post.valid_storage_at_idx(i));
            }
        }
    }
}

