fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
    let head = pre.consumer.get_Consuming_0();
    let next_head = Self::inc_wrap(head, pre.len());

    // Facts from the transition
    assert(pre.consumer == ConsumerState::Consuming(head));
    assert(post.consumer == ConsumerState::Idle(next_head));
    assert(pre.head == head);
    assert(post.head == next_head);

    // Preconditions satisfied by caller
    assert(perm.id() == pre.backing_cells.index(head as int));
    assert(perm.is_uninit());

    // In pre-state, head cell was checked out (not in storage)
    assert(pre.is_checked_out(head));
    assert(!pre.storage.dom().contains(head));

    // In pre-state, head was active (being consumed)
    assert(pre.in_active_range(head));

    // Prove post-state satisfies valid_storage_all invariant
    assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        // Case analysis on whether this is the head cell that was consumed
        if i == head {
            // This is the cell that was just returned to storage after being consumed
            assert(post.storage.dom().contains(i));

            // The deposited permission has correct cell ID
            assert(post.storage.index(i).id() == post.backing_cells.index(i as int));

            // After consumption, this cell is now uninitialized 
            // (moved from active/full to inactive/empty)
            assert(!post.in_active_range(i));
            assert(post.storage.index(i).is_uninit());

            assert(post.valid_storage_at_idx(i));
        } else {
            // This is some other cell; show its storage state is preserved correctly

            // Check if this cell is checked out in post-state
            if post.is_checked_out(i) {
                // Cell is checked out in post-state, so should not be in storage
                assert(!post.storage.dom().contains(i));
                assert(post.valid_storage_at_idx(i));
            } else {
                // Cell is in storage in post-state, verify metadata and content correctness
                assert(post.storage.dom().contains(i));
                assert(post.storage.index(i).id() == post.backing_cells.index(i as int));

                // Determine if the cell should be initialized or uninitialized
                // based on whether it's in the active range in post-state
                if post.in_active_range(i) {
                    // Should be initialized 
                    assert(post.storage.index(i).is_init());

                    // Maintain correspondence with pre-state: 
                    // if it's active now, it was active before (range only shrinks)
                    assert(pre.in_active_range(i));
                    assert(pre.storage.index(i).is_init());
                } else {
