#[inductive(consume_end)]
fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
    let head = pre.consumer.get_Consuming_0();
    let next_head = Self::inc_wrap(head, pre.len());

    // Basic transition facts from syntax
    assert(pre.consumer == ConsumerState::Consuming(head));
    assert(post.consumer == ConsumerState::Idle(next_head));
    assert(pre.head == head);
    assert(post.head == next_head);

    // Precondition requirements from transition
    assert(perm.id() == pre.backing_cells.index(head as int));
    assert(perm.is_uninit());

    // Analysis of head cell (index 'head')

    // In the pre-state:
    // - consumer is Consuming(head), so is_checked_out(head) is true
    // - Therefore, storage.dom().contains(head) should be false
    assert(pre.is_checked_out(head));
    assert(!pre.storage.dom().contains(head));

    // Also, pre.in_active_range(head) should be true (being consumed means it's full)
    assert(pre.in_active_range(head));

    // Because it was valid before, pre.valid_storage_at_idx(head) holds
    // This means: is_checked_out(head) is true AND !storage.dom().contains(head) 
    assert(pre.valid_storage_at_idx(head)); // This should follow from invariant

    // In the post-state:  
    // - consumer is Idle(next_head), so is_checked_out(head) is false
    // - head has been deposited back via deposit storage += [head => perm]
    assert(!post.is_checked_out(head));
    assert(post.storage.dom().contains(head));

    // The deposited permission becomes the storage entry
    assert(post.storage.index(head) == perm);

    // Post-state: head is no longer in active range (was consumed)
    assert(!post.in_active_range(head));  

    // Post-state: head cell is now empty (uninit) as required by deposit precondition
    assert(post.storage.index(head).is_uninit());

    // Therefore, all conditions for valid_storage_at_idx(head) hold in post-state
    assert(post.valid_storage_at_idx(head));

    // Analysis for all other cells (index i != head)
    assert forall|i: nat| 0 <= i && i < post.len() && i != head implies post.valid_storage_at_idx(i) by {
        // For any cell index i ≠ head, the transition doesn't directly affect it
        // The consumer state change only affects head position
        // The storage deposit only affects head position
        // Head advancement from head to next_head affects active range computation

        // Check if this cell is checked out in post-state
        if post.is_checked_out(i) {
            // Not checked out at head position - should be same as pre-state  
            assert(pre.is_checked_out(i)); // Consistent with pre-state
            // Validity condition for checked-out cell: !storage.dom().contains(i)
            assert(!post.storage.dom().contains(i)); 
            assert(post.valid_storage_at_idx(i));
        } else {
            // Cell is in storage in post-state
            assert(post.storage.dom().contains(i));
            // Cell ID should match backing cell
            assert(post.storage.index(i).id() == post.backing_cells.index(i as int));

            // Determine correct content based on post-state active range
            if post.in_active_range(i) {
                // Should be initialized (contains value)
                assert(post.storage.index(i).is_init());
            } else {
                // Should be uninitialized (empty)
                assert(post.storage.index(i).is_uninit());
            }
            assert(post.valid_storage_at_idx(i));
        }
    };

    // Combine cases for all indices
    assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        if i == head {
            assert(post.valid_storage_at_idx(i));
        } else {
            assert(post.valid_storage_at_idx(i)); 
        }
    };
}

