            assert(post.is_checked_out(i) == false); // now idle
            assert(post.storage.dom().contains(i));  // now in storage
            assert(post.storage.index(i).id() == post.backing_cells.index(i as int)); // correct ID
            assert(!post.in_active_range(i)); // no longer active
            assert(post.storage.index(i).is_uninit()); // now empty
            assert(post.valid_storage_at_idx(i)); // follows from definition
        } else {
            // All other cells - check their state is preserved appropriately

            // Checked out status is preserved for other cells (only head position is affected)
            assert(post.is_checked_out(i) == pre.is_checked_out(i));

            if post.is_checked_out(i) {
                // Cell remains checked out (same as before)
                assert(!post.storage.dom().contains(i));
                assert(!pre.storage.dom().contains(i)); // Was also not in storage
                assert(post.valid_storage_at_idx(i)); 
            } else {
                // Cell is stored - show its properties are preserved

                // Cell was and remains in storage (only head position was modified) 
                assert(post.storage.dom().contains(i));
                assert(pre.storage.dom().contains(i)); // Was also in storage

                // Correct cell ID association preserved
                assert(post.storage.index(i).id() == post.backing_cells.index(i as int));
                assert(pre.storage.index(i).id() == pre.backing_cells.index(i as int));

                // Content preservation based on active range membership
                if post.in_active_range(i) {
                    // Cell is active, should contain initialized value
                    assert(post.storage.index(i).is_init());

                    // If active in post-state, was also active in pre-state
                    // (active range can only shrink when head advances) 
                    assert(pre.in_active_range(i));
                    assert(pre.storage.index(i).is_init()); // was also initialized
                } else {
                    // Cell is inactive, should contain uninitialized value
                    assert(post.storage.index(i).is_uninit());

                    if pre.in_active_range(i) {
                        // Was active but is now inactive - the active range shrunk
                        // This means the head advanced past this cell  
                    } else {
                        // Was already inactive
                        assert(pre.storage.index(i).is_uninit());
                    }
                }
                assert(post.valid_storage_at_idx(i));
            }
        }
    }
}

